class Solution:
    def findAltitudes(self, elevations: List[int], targets: List[int]) -> List[int]:
        out = []
        for t in targets:
            idx = -1
            for i, v in enumerate(elevations):
                if v == t:
                    idx = i
                    break
            out.append(idx)
        return out

