class Solution {
    public int[] findAltitudes(int[] elevations, int[] targets) {
        int[] out = new int[targets.length];
        for (int q = 0; q < targets.length; q++) {
            out[q] = -1;
            for (int i = 0; i < elevations.length; i++) if (elevations[i] == targets[q]) { out[q] = i; break; }
        }
        return out;
    }
}

