    vector<int> findAltitudes(vector<int>& elevations, vector<int>& targets) {
        vector<int> out;
        for (int t : targets) {
            auto it = find(elevations.begin(), elevations.end(), t);
            out.push_back(it == elevations.end() ? -1 : (int) (it - elevations.begin()));
        }
        return out;
    }
};

