class Solution {
    public int[] findAltitudes(int[] elevations, int[] targets) {
        Map<Integer, Integer> first = new HashMap<>();
        for (int i = 0; i < elevations.length; i++) first.putIfAbsent(elevations[i], i);
        int[] out = new int[targets.length];
        for (int q = 0; q < targets.length; q++) out[q] = first.getOrDefault(targets[q], -1);
        return out;
    }
}

