    vector<int> findAltitudes(vector<int>& elevations, vector<int>& targets) {
        unordered_map<int, int> first;
        for (int i = 0; i < (int) elevations.size(); i++) first.emplace(elevations[i], i);
        vector<int> out;
        for (int t : targets) {
            auto it = first.find(t);
            out.push_back(it == first.end() ? -1 : it->second);
        }
        return out;
    }
};

