typedef struct { int key; int idx; bool used; } Slot;

static Slot* slotFor(Slot* t, unsigned mask, int key) {
    unsigned long long h = (unsigned long long) (long long) key * 0x9E3779B97F4A7C15ULL;
    unsigned s = (unsigned) (h >> 32) & mask;
    while (t[s].used && t[s].key != key) s = (s + 1) & mask;
    return &t[s];
}

int* findAltitudes(int* elevations, int elevationsSize, int* targets, int targetsSize, int* returnSize) {
    unsigned cap = 1;
    while (cap < 2u * elevationsSize) cap <<= 1;
    Slot* first = calloc(cap, sizeof(Slot));
    for (int i = 0; i < elevationsSize; i++) {
        Slot* s = slotFor(first, cap - 1, elevations[i]);
        if (!s->used) *s = (Slot) {elevations[i], i, true};
    }
    int* out = malloc(targetsSize * sizeof(int));
    for (int q = 0; q < targetsSize; q++) {
        Slot* s = slotFor(first, cap - 1, targets[q]);
        out[q] = s->used ? s->idx : -1;
    }
    free(first);
    *returnSize = targetsSize;
    return out;
}

