class Solution:
    def findAltitudes(self, elevations: List[int], targets: List[int]) -> List[int]:
        e, n = elevations, len(elevations)
        lo, hi = 0, n - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if e[mid] < e[mid + 1]:
                lo = mid + 1
            else:
                hi = mid
        top = lo
        out = []
        for t in targets:
            lo, hi = 0, top + 1
            while lo < hi:
                mid = (lo + hi) // 2
                if e[mid] < t:
                    lo = mid + 1
                else:
                    hi = mid
            if lo <= top and e[lo] == t:
                out.append(lo)
                continue
            lo, hi = top, n
            while lo < hi:
                mid = (lo + hi) // 2
                if e[mid] > t:
                    lo = mid + 1
                else:
                    hi = mid
            out.append(lo if lo < n and e[lo] == t else -1)
        return out

