class Solution {
    public int[] findAltitudes(int[] e, int[] targets) {
        int n = e.length, lo = 0, hi = n - 1;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (e[mid] < e[mid + 1]) lo = mid + 1; else hi = mid;
        }
        int top = lo;
        int[] out = new int[targets.length];
        for (int q = 0; q < targets.length; q++) {
            int t = targets[q];
            lo = 0; hi = top + 1;
            while (lo < hi) {
                int mid = lo + (hi - lo) / 2;
                if (e[mid] < t) lo = mid + 1; else hi = mid;
            }
            if (lo <= top && e[lo] == t) { out[q] = lo; continue; }
            lo = top; hi = n;
            while (lo < hi) {
                int mid = lo + (hi - lo) / 2;
                if (e[mid] > t) lo = mid + 1; else hi = mid;
            }
            out[q] = (lo < n && e[lo] == t) ? lo : -1;
        }
        return out;
    }
}

