class Solution {
public:
    vector<int> findAltitudes(vector<int>& e, vector<int>& targets) {
        int n = e.size(), lo = 0, hi = n - 1;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (e[mid] < e[mid + 1]) lo = mid + 1; else hi = mid;
        }
        int top = lo;
        vector<int> out;
        for (int t : targets) {
            int i = lower_bound(e.begin(), e.begin() + top + 1, t) - e.begin();
            if (i <= top && e[i] == t) { out.push_back(i); continue; }
            int j = lower_bound(e.begin() + top, e.end(), t, greater<int>()) - e.begin();
            out.push_back(j < n && e[j] == t ? j : -1);
        }
        return out;
    }
};

